use vstd::prelude::*;

verus! {

    // Compute the longest common prefix of two character vectors.
    // The result satisfies:
    // 1. Its length is ≤ each input's length.
    // 2. Every index in the result matches in both inputs.
    // 3. It is maximal: either it exhausts one input, or the next characters differ.
    fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> (result: Vec<char>)
        ensures
            // result.len() ≤ str1.len() and ≤ str2.len()
            result.len() <= str1.len(),
            result.len() <= str2.len(),
            // shared-character property
            forall|i: int|
                0 <= i && i < result.len() as int ==>
                    result[i as usize] == str1[i as usize] &&
                    result[i as usize] == str2[i as usize],
            // maximality
            result.len() == str1.len() ||
            result.len() == str2.len() ||
            ( result.len() < str1.len() &&
              result.len() < str2.len() &&
              str1[result.len()] != str2[result.len()] )
    {
        // Build up the prefix one character at a time.
        let mut result: Vec<char> = Vec::new();

        let len1 = str1.len();
        let len2 = str2.len();
        // Compute the minimum of the two lengths.
        let min_len = if len1 <= len2 { len1 } else { len2 };

        let mut idx: usize = 0;
        // While we haven't reached the end of one vector
        // and the characters still match, extend the prefix.
        while idx < min_len && str1[idx] == str2[idx]
            invariant
                // idx never exceeds either input length or the min length
                idx <= len1,
                idx <= len2,
                idx <= min_len,
                // result.len() == idx
                result.len() == idx,
                // prefix-equality invariant
                forall|j: int|
                    0 <= j && j < idx as int ==>
                        result[j as usize] == str1[j as usize] &&
                        result[j as usize] == str2[j as usize],
            decreases
                // measure decreases every iteration
                min_len - idx
        {
            result.push(str1[idx]);
            idx += 1;
        }

        // Now idx == result.len().
        assert(result.len() == idx);

        //
        // Prove the maximality / exhaustion disjunction.
        //
        // We do a case‐split on which string is shorter.
        if len1 <= len2 {
            // then min_len == len1
            assert(min_len == len1);
            if idx == min_len {
                // we've consumed all of str1
                assert(result.len() == str1.len());
            } else {
                // idx < min_len == len1 ≤ len2
                assert(idx < len1 && idx < len2);
                // loop stopped because characters differ
                assert(str1[idx] != str2[idx]);
            }
        } else {
            // len1 > len2, so min_len == len2
            assert(min_len == len2);
            if idx == min_len {
                // we've consumed all of str2
                assert(result.len() == str2.len());
            } else {
                // idx < min_len == len2 < len1
                assert(idx < len2 && idx < len1);
                assert(str1[idx] != str2[idx]);
            }
        }

        result
    }

} // end verus!

